import{_ as i,h as o,i as e,c as n,v as r,p as s,x as t,m as h,e as A,S as d}from"./chunks/framework.Dvtg8yj2.js";const V=JSON.parse('{"title":"共享 KV 下的训练稳定性","description":"","frontmatter":{"title":"共享 KV 下的训练稳定性","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/shared-kv-training.md","filePath":"llm/shared-kv-training.md","lastUpdated":1788454257000}'),p={name:"llm/shared-kv-training.md"};function m(_,a,E,c,f,u){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="共享-kv-下的训练稳定性" tabindex="-1">共享 KV 下的训练稳定性 <a class="header-anchor" href="#共享-kv-下的训练稳定性" aria-label="Permalink to &quot;共享 KV 下的训练稳定性&quot;">​</a></h1><div class="epigraph"><p>不必从零再训一遍：把多头检查点的键值头按组平均，再接着训练，就能得到分组查询，且质量往往跟得上。</p><footer>—— Joshua Ainslie 等, GQA, 2023</footer></div><p><a href="/llm/mqa">MQA</a> 与 <a href="/llm/gqa">GQA</a> 在推理侧把多套查询接到同一套键值上，缓存立刻变瘦。训练侧却没有同样轻松：共享意味着许多查询头的梯度灌进同一对 \\(W_K,W_V\\)，容量变小，优化路径也变窄。Ainslie 等人 2023 年给出的升训办法——从多头检查点池化键值再继续训——是目前最常用的稳定化路径；Shazeer 2019 年的 MQA 则主要是从零训。本篇只讨论共享 KV 时损失为什么抖、升训为什么有效、哪些超参能把曲线按住，不回头讲头数–吞吐曲线，那根轴见 <a href="/llm/kv-head-tradeoff">KV 头数、质量与吞吐的权衡</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完整多头里，每个头有自己的 \\(W_K^{(h)},W_V^{(h)}\\)。损失对第 \\(h\\) 头键值的梯度只经过该头的注意力权重。改成组共享后，一组 \\(g\\) 个查询头共用 \\(W_K^{(g)},W_V^{(g)}\\)，反向变成</p> \\[\\frac{\\partial\\mathcal{L}}{\\partial W_K^{(g)}}=\\sum_{h\\in g}\\frac{\\partial\\mathcal{L}}{\\partial W_K^{(h)}} \\]<p>若干头的误差叠加在同一份参数上。若这些头原先编码的模式互相冲突，梯度会互相抵消，表现为损失平台或突然尖峰。<span class="marginnote">共享不是把 \\(g\\) 个头的矩阵拼起来平均那么简单。前向已经强迫它们读同一套键；反向再把冲突的监督加在一起，等于缩小可行域。升训要做的，是让这一套键值重新学会伺候整组查询。</span>从零训 MQA 时，模型从未见过「每头一套键」的过参数化，早期尚可；一旦数据变难、上下文变长，容量缺口会在验证集上慢慢拉开。从 MHA 直接改图却不升训，等于把已经特化的头硬并在一起，几乎必掉点。</p><p>服务端常希望「已经训好的 32 头模型，推理改 8 头就上线」。图可以改，权重不能直接用：MHA 的 32 套 \\(K\\) 没有对齐到 8 组的语义上。稳定性问题因此有两张脸：从零共享时的容量与梯度噪声，以及改图之后的分布突变。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="从零训练与从-mha-升训" tabindex="-1">从零训练与从 MHA 升训 <a class="header-anchor" href="#从零训练与从-mha-升训" aria-label="Permalink to &quot;从零训练与从 MHA 升训&quot;">​</a></h3><p>从零共享最干净：网络一开始就是 \\(h_{\\mathrm{kv}}&lt;h_q\\)，优化器不必消化一次结构休克。代价是总训练预算要按共享架构重新花，无法复用已有多头检查点。数据与算力充足、目标本来就是 MQA 的解码器，这条路最稳。</p><p>升训是 Ainslie 等人的核心贡献。给定 MHA 检查点，把相邻或按索引分组的 KV 头做均值池化，得到 GQA 的初始 \\(W_K,W_V\\)，查询头保持不动，然后用原数据或蒸馏数据再训一小段。前向立刻变成共享图，但参数从「有意义的平均」起步，而不是随机。经验上，升训步数远小于预训练总步数，就能把掉点收回大半。这把「共享 KV」从一次架构豪赌，变成一次可调度的后训练工序。</p>',12)),(e(),s(d,null,{default:t(()=>[A(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%A4%9A%E5%A4%B4%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20B%5B%22%E6%8C%89%E7%BB%84%E6%B1%A0%E5%8C%96%20KV%20%E5%A4%B4%22%5D%0A%20%20B%20--%3E%20C%5B%22GQA%20%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%0A%20%20C%20--%3E%20D%5B%22%E7%9F%AD%E6%AD%A5%E6%95%B0%E5%8D%87%E8%AE%AD%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%85%B1%E4%BA%AB%20KV%20%E5%8F%AF%E9%83%A8%E7%BD%B2%22%5D%0A%20%20F%5B%22%E9%9A%8F%E6%9C%BA%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%20--%3E%20G%5B%22%E4%BB%8E%E9%9B%B6%E8%AE%AD%20MQA%20%E6%88%96%20GQA%22%5D%0A%20%20G%20--%3E%20E%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="梯度耦合与容量瓶颈" tabindex="-1">梯度耦合与容量瓶颈 <a class="header-anchor" href="#梯度耦合与容量瓶颈" aria-label="Permalink to &quot;梯度耦合与容量瓶颈&quot;">​</a></h3><p>耦合来自求和。令一组内两个查询头分别想把某个位置的键推到不同方向，更新会近似抵消，学习率再大也只是在噪声里振荡。容量瓶颈来自秩：一套 \\(d_h\\) 维的键要解释 \\(g\\) 套查询，相当于把原来 \\(g\\cdot d_h\\) 的键空间压到 \\(d_h\\)。若任务需要的独立模式数超过这个秩，训练不会发散，但会停在更高的损失平台上，看起来像「学不动」。</p><p>可操作的判据是分组后的损失间隙。升训开始后几十步，训练损失应回到改图前的附近；若长期高一截，多半是组太大，应增加 \\(h_{\\mathrm{kv}}\\) 而不是盲目加大学习率。学习率过大时，叠加梯度会把共享键值打飞，出现与普通损失尖峰相似、但只在注意力层放大的现象。这时应先对 KV 投影单独降学习率或加梯度裁剪，而不是整网降学习率。</p><h3 id="稳定化的常见做法" tabindex="-1">稳定化的常见做法 <a class="header-anchor" href="#稳定化的常见做法" aria-label="Permalink to &quot;稳定化的常见做法&quot;">​</a></h3><p>几件事反复有效。第一，池化要对齐：同一组应取在 MHA 里已经相近的头，随机乱组会加大升训负担。第二，升训阶段保持预归一化、权重衰减与数据配比不变，只改注意力图，减少变量。第三，对 \\(W_K,W_V\\) 用更小的学习率，对 \\(W_Q\\) 保持原学习率，让查询头去适配共享键，而不是让键剧烈搬家。第四，升训数据略偏长序列，迫使共享键值学会在更长距离上被多路查询使用。第五，若目标是 MQA，可先升到 GQA-8，再升到 GQA-4 或 MQA，阶梯比一次并到单头更稳。</p><p><span class="marginnote">阶梯升训的直觉是：每次只把组扩大一倍，梯度冲突的增量有限，优化器来得及把键值重新对齐。一次从 32 头并到 1 头，等于同时引入 31 路冲突，尖峰概率明显上升。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>共享之后，前向的注意力权重仍按查询头独立 softmax，差异来自 \\(q_h\\)。反向则在键值处汇合。可以把共享层看成一个多任务瓶颈：每个查询头是一个任务，键值是共享骨干。多任务学习里骨干学习率偏低、任务头学习率偏高，与上面「KV 小步、Q 大步」一致。</p><p>数值上，softmax 对键的梯度带着 \\(\\mathrm{softmax}(\\cdot)\\) 的雅可比，本身已有饱和区。多头梯度相加后，范数可能比单头大 \\(\\sqrt{g}\\) 量级。若不按 \\(g\\) 缩放学习率或裁剪阈值，Adam 的二阶动量会把共享层的有效步长推离其余层，表现为「只有注意力不稳」。把 KV 梯度除以 \\(g\\) 或按组做一次平均再写参数，是和池化初始化配套的细节。</p><p>MLA 的瓶颈在潜维，不在头数，训练动态不同：低秩投影有自己的病态条件数，稳定手段是对潜向量做 RMSNorm 或调秩，而不是池化头。不要把 GQA 升训脚本套到 MLA 上。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>升训不是万能。若原 MHA 模型在长上下文上本就弱，池化再训救不回外推；应先解决位置编码与窗口，再减头。蒸馏升训依赖教师分布，教师若是完整多头，学生共享 KV 无法拟合全部注意力熵，KL 会有下界，这时应混一点真实数据的最大似然，避免学生只学会模仿教师的「每头各异」的权重。</p><p>并行也会搅稳定性。张量并行按头切时，一组 KV 头必须落在同一通信域，否则前向要广播共享键、反向要跨卡加梯度，既慢又引入额外的同步噪声。组数应整除并行度。混合精度下，多头梯度相加更容易溢出 FP16，共享层更该用 BF16 或对注意力分数保持更高精度。</p><p>取舍上：有检查点就升训，没有检查点且预算充足就从零训；不要在推理图上改 \\(h_{\\mathrm{kv}}\\) 却期望质量不变。端侧若必须 MQA，优先在预训练后半段就切到共享，而不是上线前临时并头。<span class="marginnote">「推理改头、权重不动」只适合做延迟探针，不适合当产品质量。没有升训的共享 KV，掉的是检索与指代，平均困惑度往往还假装没事。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享 KV 把多路查询的梯度加进同一套 \\(W_K,W_V\\)，冲突表现为平台或尖峰，而不是单纯的显存变小。</li><li>从零训结构一致、预算高；从 MHA 池化再升训，是复用检查点的稳妥路径。</li><li>升训应保持数据与归一化不变，KV 学习率偏低、查询头适配，必要时阶梯减头。</li><li>梯度范数随组大小上涨，需要按组缩放或裁剪，混合精度更敏感。</li><li>MLA 的稳定问题在低秩，不在并头，不能套 GQA 升训。</li><li>没有升训的改图只能测吞吐，不能当最终质量。</li><li>出处：Shazeer, <em>Fast Transformer Decoding</em>, 2019；Ainslie et al., <em>GQA: Training Generalized Multi-Query Transformer Models from Multi-Head Checkpoints</em>, 2023。</li></ul>',16))])}const K=i(p,[["render",m]]);export{V as __pageData,K as default};
